import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String next;
        switch (input) {
            case "init": next = "start"; break;
            case "start": next = "stop"; break;
            case "stop": next = "destroy"; break;
            default: System.exit(1); return;
        }
        System.out.println(next);
    }
}

