import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String[] all = {"init", "start", "stop", "destroy"};
        int start = 0;
        for (int i = 0; i < all.length; i++) if (all[i].equals(input)) { start = i; break; }
        StringBuilder sb = new StringBuilder();
        for (int i = start; i < all.length; i++) { if (sb.length() > 0) sb.append(" "); sb.append(all[i]); }
        System.out.println(sb);
    }
}
